import{_ as n,o as a,c as l,aw as o}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"Фунарг-проблема","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/js-function/closures/funarg.md","filePath":"wiki/dev-commit/js/js-function/closures/funarg.md"}'),e={name:"wiki/dev-commit/js/js-function/closures/funarg.md"};function p(t,s,c,r,i,u){return a(),l("div",null,[...s[0]||(s[0]=[o(`<h1 id="фунарг-проблема" tabindex="-1">Фунарг-проблема <a class="header-anchor" href="#фунарг-проблема" aria-label="Permalink to &quot;Фунарг-проблема&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li><a href="http://dmitrysoshnikov.com/ecmascript/ru-chapter-6-closures/#funarg-problema" target="_blank" rel="noreferrer">http://dmitrysoshnikov.com/ecmascript/ru-chapter-6-closures/#funarg-problema</a> - Тонкости ECMA-262-3</li></ul></div><h2 id="фунарг" tabindex="-1">Фунарг <a class="header-anchor" href="#фунарг" aria-label="Permalink to &quot;Фунарг&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Определение</p><ul><li><strong>Фунарг</strong> - сокращение от «функциональный аргумент»</li></ul></div><ul><li>В <em>стековых</em> языках программирования, локальные переменные функции хранятся в стеке, который наполняется новыми элементами при выполнении функции. При выходе из функции, эти переменные удаляются из стека</li><li><em>Ограничения</em> для использования функций при &quot;возврате из функции&quot; и при &quot;передаче в виде аргумента&quot;</li></ul><h3 id="решение" tabindex="-1">Решение <a class="header-anchor" href="#решение" aria-label="Permalink to &quot;Решение&quot;">​</a></h3><ul><li>Использование замыканий</li></ul><h2 id="виды" tabindex="-1">Виды <a class="header-anchor" href="#виды" aria-label="Permalink to &quot;Виды&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Определение</p><ul><li><strong>Проблема восходящего фунарга</strong> (upward funarg) - возникает при возврате функции из некоторой функции</li><li><strong>Проблема нисходящего фунарга</strong> (downward funarg) - возникает при передаче функции в качестве параметра некоторой функции</li></ul></div><h2 id="проблема-1-свободные-переменные" tabindex="-1">Проблема #1: Свободные переменные <a class="header-anchor" href="#проблема-1-свободные-переменные" aria-label="Permalink to &quot;Проблема #1: Свободные переменные&quot;">​</a></h2><ul><li>Наиболее характерно Фунарг-проблема проявляется при использовании в функции свободных переменных</li></ul><div class="tip custom-block"><p class="custom-block-title">Определение</p><ul><li><strong>Свободная переменная</strong> (Free variable) - переменная, используемая функцией, но не являющаяся ни параметром, ни локальной переменной этой функции</li></ul></div><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">function</span><span style="color:#4078F2;"> testFn</span><span style="color:#383A42;">() {</span></span>
<span class="line"><span style="color:#A626A4;">  const</span><span style="color:#986801;"> localVar</span><span style="color:#0184BC;"> =</span><span style="color:#986801;"> 10</span><span style="color:#383A42;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A626A4;">  function</span><span style="color:#4078F2;"> innerFn</span><span style="color:#383A42;">(innerParam) {</span></span>
<span class="line"><span style="color:#383A42;">    console.</span><span style="color:#4078F2;">log</span><span style="color:#383A42;">(innerParam </span><span style="color:#0184BC;">+</span><span style="color:#383A42;"> localVar);</span></span>
<span class="line"><span style="color:#383A42;">  }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A626A4;">  return</span><span style="color:#383A42;"> innerFn;</span></span>
<span class="line"><span style="color:#383A42;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> someFn</span><span style="color:#0184BC;"> =</span><span style="color:#4078F2;"> testFn</span><span style="color:#383A42;">();</span></span>
<span class="line"><span style="color:#4078F2;">someFn</span><span style="color:#383A42;">(</span><span style="color:#986801;">20</span><span style="color:#383A42;">); </span><span style="color:#A0A1A7;font-style:italic;">// 30</span></span></code></pre></div><ul><li>В данном случае, для функции <em>innerFn</em> свободной переменной является <em>localVar</em></li><li>Если бы в данной системе использовалась стековая реализация для хранения локальных переменных, это означало бы, что по завершении функции <em>testFn</em>, все её локальные переменные должны были бы удалиться из стека, что привело бы к ошибке при вызове функции <em>innerFn</em> снаружи посредством <em>someFn</em></li><li>В данном случае, при стековой организации, и сам возврат функции <em>innerFn</em> был бы невозможен, т.к. <em>innerFn</em> так же является локальной функцией для функции <em>testFn</em> и будет удалена по завершению <em>testFn</em></li></ul><h2 id="проблема-2-передача-функции-в-качестве-аргумента" tabindex="-1">Проблема #2: Передача функции в качестве аргумента <a class="header-anchor" href="#проблема-2-передача-функции-в-качестве-аргумента" aria-label="Permalink to &quot;Проблема #2: Передача функции в качестве аргумента&quot;">​</a></h2><ul><li>Проблема возникает при организации системы с <em>динамической областью видимости</em></li></ul><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> x</span><span style="color:#0184BC;"> =</span><span style="color:#986801;"> 10</span><span style="color:#383A42;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A626A4;">function</span><span style="color:#4078F2;"> someFn</span><span style="color:#383A42;">() {</span></span>
<span class="line"><span style="color:#383A42;">  console.</span><span style="color:#4078F2;">log</span><span style="color:#383A42;">(x);</span></span>
<span class="line"><span style="color:#383A42;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#4078F2;">someFn</span><span style="color:#383A42;">(); </span><span style="color:#A0A1A7;font-style:italic;">// 10 - и при статической и при динамической Scope</span></span>
<span class="line"></span>
<span class="line"><span style="color:#383A42;">(</span><span style="color:#A626A4;">function</span><span style="color:#383A42;"> () {</span></span>
<span class="line"><span style="color:#A626A4;">  const</span><span style="color:#986801;"> x</span><span style="color:#0184BC;"> =</span><span style="color:#986801;"> 20</span><span style="color:#383A42;">;</span></span>
<span class="line"><span style="color:#4078F2;">  someFn</span><span style="color:#383A42;">(); </span><span style="color:#A0A1A7;font-style:italic;">// 10 - при статической, 20 - при динамической Scope</span></span>
<span class="line"><span style="color:#383A42;">})();</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// Аналогично, при передаче someFn</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// в качестве параметра</span></span>
<span class="line"></span>
<span class="line"><span style="color:#383A42;">(</span><span style="color:#A626A4;">function</span><span style="color:#383A42;"> (funArg) {</span></span>
<span class="line"><span style="color:#A626A4;">  const</span><span style="color:#986801;"> x</span><span style="color:#0184BC;"> =</span><span style="color:#986801;"> 30</span><span style="color:#383A42;">;</span></span>
<span class="line"><span style="color:#4078F2;">  funArg</span><span style="color:#383A42;">(); </span><span style="color:#A0A1A7;font-style:italic;">// 10 - при статической, 30 - при динамической Scope</span></span>
<span class="line"><span style="color:#383A42;">})(someFn);</span></span></code></pre></div><ul><li>При организации системы с динамической областью видимости, разрешение имени переменной осуществляется в пределах динамического (активного) стека переменных (свободная переменная ищется в динамической цепи вызова, а не в статической цепи создания функции), что может привести к неоднозначности</li><li>При этом, даже, если <em>x</em> будет определена (в отличие от предыдущего примера, где локальные переменные удалились бы из стека и были бы не определены), возникнет вопрос, какое из значений <em>x</em> (точнее, <em>x</em> из какого контекста, какой области видимости) должно использоваться в различных вызовах функции <em>someFn</em>?</li></ul>`,19)])])}const A=n(e,[["render",p]]);export{m as __pageData,A as default};
